test_that("the saved full Julia fit retains native optimized and uncertainty parity", {
  reference <- readRDS(testthat::test_path(
    "fixtures", "native-full-uncertainty-oracle.rds"
  ))
  fit <- FIMS::fit_big_optimized
  expect_equal(get_number_of_parameters(fit),
    c(fixed_effects = 49L, random_effects = 29L))
  expect_equal(get_opt(fit)[["convergence"]], 0L)
  expect_true(get_sdreport(fit)[["pdHess"]])
  expect_lt(get_max_gradient(fit), 1e-3)
  expect_equal(get_opt(fit)[["objective"]], reference[["marginal"]], tolerance = 1e-6)
  keys <- c("module_name", "fleet", "label", "year_i", "age", "length")
  parameters <- get_estimates(fit) |>
    dplyr::filter(.data$estimation_type %in% c("fixed_effects", "random_effects"))
  matched <- dplyr::inner_join(
    reference[["parameters"]], parameters, by = keys,
    suffix = c("_native", "_julia"), relationship = "one-to-one"
  )
  expect_equal(nrow(parameters), 78L)
  expect_equal(nrow(matched), 78L)
  expect_equal(matched[["estimated_julia"]], matched[["estimated_native"]],
    tolerance = 1e-4)
  expect_equal(unname(matched[["uncertainty_julia"]]),
    unname(matched[["uncertainty_native"]]), tolerance = 1e-4)
  covariance <- environment(get_obj(fit)[["fn"]])[["fit_result"]][["covariance"]]
  indices <- matched[["parameter_id_julia"]]
  expect_equal(unname(covariance[indices, indices]),
    reference[["covariance"]], tolerance = 1e-4)
  derived <- get_estimates(fit) |>
    dplyr::filter(.data$estimation_type == "derived_quantity") |>
    dplyr::inner_join(
      reference[["derived"]], by = keys,
      suffix = c("_julia", "_native"), relationship = "one-to-one"
    )
  expect_equal(nrow(derived), nrow(reference[["derived"]]))
  for (label in unique(reference[["derived"]][["label"]])) {
    rows <- derived |>
      dplyr::filter(.data$label == .env$label)
    expect_equal(unname(rows[["uncertainty_julia"]]),
      unname(rows[["uncertainty_native"]]), tolerance = 1e-4, info = label)
    expect_equal(
      unname(unlist(get_report(fit)[[label]])),
      unname(unlist(reference[["report"]][[label]])),
      tolerance = 1e-4, info = label
    )
  }
})

test_that("real Julia fits retain the saved optimized native comparisons", {
  skip_if(Sys.getenv("FIMS_RUN_JULIA_INTEGRATION") != "true",
    "Set FIMS_RUN_JULIA_INTEGRATION=true to exercise the real Julia bridge.")
  oracle <- readRDS(testthat::test_path("fixtures", "native-backend-oracle.rds"))
  for (case in oracle[["optimized"]]) {
    fit <- initialize_fims(case[["parameters"]], FIMSFrame(oracle[["data"]])) |>
      fit_fims(number_of_loops = 0)
    expect_equal(get_opt(fit)[["convergence"]], 0L, info = case[["name"]])
    expect_true(get_sdreport(fit)[["pdHess"]], info = case[["name"]])
    expect_equal(get_opt(fit)[["objective"]], case[["marginal"]],
      tolerance = 1e-6, info = case[["name"]])
    expect_equal(get_report(fit)[["jnll"]], case[["joint"]],
      tolerance = 1e-6, info = case[["name"]])
    estimates <- get_estimates(fit) |>
      dplyr::filter(.data$estimation_type %in% c("fixed_effects", "random_effects")) |>
      dplyr::arrange(.data$module_name, .data$fleet, .data$label) |>
      dplyr::mutate(uncertainty = unname(.data$uncertainty)) |>
      dplyr::select(dplyr::all_of(c("module_name", "fleet", "label", "estimated", "uncertainty")))
    expect_true(all(is.finite(estimates[["uncertainty"]])))
    expect_equal(estimates, case[["estimates"]], tolerance = 1e-4, info = case[["name"]])
    expect_lt(get_max_gradient(fit), 1e-3)
    expect_equal(nrow(summary(get_sdreport(fit), "fixed")),
      get_number_of_parameters(fit)[["fixed_effects"]])
    objective <- get_obj(fit)
    changed_parameters <- objective[["par"]] + 0.01
    changed_value <- objective[["fn"]](changed_parameters)
    clear()
    expect_equal(objective[["fn"]](changed_parameters), changed_value)
    if (grepl("FALSE", case[["name"]], fixed = TRUE)) {
      set.seed(19)
      original <- objective[["simulate"]]()
      set.seed(19)
      changed <- objective[["simulate"]](changed_parameters)
      index <- original[["observed_index"]]
      present <- is.finite(index) & index != -999
      expect_equal(changed[["observed_index"]][present],
        index[present] * exp(0.01))
    }
  }
})

test_that("native random-prior reference includes the prior before Laplace integration", {
  oracle <- readRDS(testthat::test_path("fixtures", "native-random-prior-oracle.rds"))
  for (case in oracle[["cases"]]) {
    priors <- case[["priors"]]
    random <- which(case[["parameters_table"]][["estimation_type"]] == "random_effects")
    fixed <- setdiff(seq_len(nrow(case[["parameters_table"]])), random)
    random_priors <- which(case[["prior_coordinates"]] %in% random)
    expected_curvature <- diag(0, length(random))
    diag(expected_curvature)[match(case[["prior_coordinates"]][random_priors], random)] <-
      1 / priors[["sd"]][random_priors]^2
    prior_nll <- function(parameters) {
      values <- parameters[case[["prior_coordinates"]]]
      normal <- priors[["distribution"]] == "dnorm"
      -sum(stats::dnorm(values[normal], priors[["mean"]][normal],
        priors[["sd"]][normal], log = TRUE)) -
        sum(stats::dlnorm(values[!normal], priors[["mean"]][!normal],
          priors[["sd"]][!normal], log = TRUE))
    }
    for (point in c(case[["points"]], list(case[["conditional"]]))) {
      parameters <- point[["parameters"]]
      expect_equal(point[["joint"]] - point[["native_joint"]],
        prior_nll(parameters), tolerance = 1e-12)
      expect_equal(point[["random_hessian"]] - point[["native_random_hessian"]],
        expected_curvature, tolerance = 1e-12)
      expect_equal(point[["marginal"]] - point[["joint"]],
        as.numeric(determinant(point[["random_hessian"]], logarithm = TRUE)[["modulus"]]) / 2 -
          length(random) * log(2 * pi) / 2, tolerance = 1e-12)
      prior_score <- purrr::map_dbl(random, function(index) {
        upper <- lower <- parameters
        upper[[index]] <- upper[[index]] + 1e-5
        lower[[index]] <- lower[[index]] - 1e-5
        (prior_nll(upper) - prior_nll(lower)) / 2e-5
      })
      expect_lt(max(abs(point[["native_gradient"]][random] + prior_score)), 1e-6)
    }
    covariance <- case[["covariance"]]
    sensitivity <- case[["random_fixed_sensitivity"]]
    expect_equal(covariance[fixed, fixed], solve(case[["fixed_hessian"]]), tolerance = 1e-10)
    expect_equal(covariance[random, random] -
      sensitivity %*% covariance[fixed, fixed] %*% t(sensitivity),
      solve(case[["conditional"]][["random_hessian"]]), tolerance = 1e-10)
  }
  control <- oracle[["cases"]][["EWAA-fixed-prior-control"]][["points"]][[1]]
  augmented <- oracle[["cases"]][["EWAA-random-priors"]][["points"]][[1]]
  expect_gt(max(abs(control[["parameters"]] - augmented[["parameters"]])), 0.01)
  expect_gt(abs(oracle[["post_marginal_counterexample"]][["incorrect_marginal"]] -
    augmented[["marginal"]]), 1e-3)
})

test_that("native DoubleLogistic reference identifies both limbs in both fleets", {
  oracle <- readRDS(testthat::test_path("fixtures", "native-double-logistic-oracle.rds"))
  case <- oracle[["cases"]][["DoubleLogistic-joint"]]
  for (fleet_index in seq_along(c("fleet1", "survey1"))) {
    fleet <- c("fleet1", "survey1")[[fleet_index]]
    selectivity <- case[["parameters_table"]] |>
      dplyr::filter(.data$module_name == "Selectivity", .data$fleet == .env$fleet)
    truth <- oracle[["truth"]][["parameters"]] |>
      dplyr::filter(.data$module_name == "Selectivity", .data$fleet == .env$fleet)
    truth_values <- truth[["value"]][match(selectivity[["label"]], truth[["label"]])]
    expect_lt(max(abs(selectivity[["estimated"]] - truth_values)), 0.1)
    expect_true(all(selectivity[["uncertainty"]] > 0 & selectivity[["uncertainty"]] < 0.3))
    for (specification in list(
      c("age_comp", "agecomp_expected", "age"),
      c("length_comp", "lengthcomp_expected", "length")
    )) {
      observations <- case[["data"]] |>
        dplyr::filter(.data$fleet == .env$fleet, .data$type == specification[[1]]) |>
        dplyr::arrange(.data$timing, .data[[specification[[3]]]])
      bins <- dplyr::n_distinct(observations[[specification[[3]]]])
      observed <- matrix(observations[["observed"]], nrow = bins)
      expected <- matrix(
        oracle[["truth"]][["report"]][[specification[[2]]]][[fleet_index]], nrow = bins
      )
      expected <- sweep(expected, 2, colSums(expected), "/")
      expect_equal(colSums(observed), rep(1, ncol(observed)), tolerance = 1e-12)
      expect_equal(200 * observed, round(200 * observed), tolerance = 1e-12)
      expect_lt(max(abs(observed - expected)), 1 / 200)
    }
  }
  expect_gt(min(eigen(case[["covariance"]], symmetric = TRUE, only.values = TRUE)[["values"]]), 0)
  expect_equal(solve(case[["fixed_hessian"]]), solve(case[["check_fixed_hessian"]]), tolerance = 1e-5)
  random <- which(case[["parameters_table"]][["estimation_type"]] == "random_effects")
  for (point in case[["points"]]) {
    expect_lt(max(abs(point[["joint_gradient"]][random])), 1e-6)
    expect_equal(as.numeric(point[["marginal"]] - point[["report"]][["jnll"]]),
      as.numeric(determinant(point[["joint_hessian"]][random, random],
        logarithm = TRUE)[["modulus"]]) / 2 - length(random) * log(2 * pi) / 2,
      tolerance = 1e-12)
  }
})

