test_that("real Julia joint configurations retain native gradients and uncertainty", {
  skip_if(Sys.getenv("FIMS_RUN_JULIA_INTEGRATION") != "true",
    "Set FIMS_RUN_JULIA_INTEGRATION=true to exercise real Julia configuration fits.")
  oracle <- readRDS(testthat::test_path("fixtures", "native-configuration-oracle.rds"))
  random_prior_oracle <- readRDS(testthat::test_path("fixtures", "native-random-prior-oracle.rds"))
  double_logistic_oracle <- readRDS(testthat::test_path("fixtures", "native-double-logistic-oracle.rds"))
  static_selectivity_oracle <- readRDS(testthat::test_path("fixtures", "native-static-selectivity-oracle.rds"))
  yearly_selectivity_oracle <- readRDS(testthat::test_path("fixtures", "native-yearly-selectivity-oracle.rds"))
  growth_delta_oracle <- readRDS(testthat::test_path("fixtures", "native-growth-delta-oracle.rds"))
  proportion_female_oracle <- readRDS(testthat::test_path("fixtures", "native-proportion-female-oracle.rds"))
  heterogeneous_oracle <- readRDS(testthat::test_path("fixtures", "native-heterogeneous-observation-oracle.rds"))
  recruitment_oracle <- readRDS(testthat::test_path("fixtures", "native-recruitment-process-oracle.rds"))
  cases <- c(oracle[["cases"]], random_prior_oracle[["cases"]],
    double_logistic_oracle[["cases"]], static_selectivity_oracle[["cases"]],
    yearly_selectivity_oracle[["cases"]], growth_delta_oracle[["cases"]],
    proportion_female_oracle[["cases"]], heterogeneous_oracle[["cases"]],
    recruitment_oracle[["cases"]])
  random_prior_results <- list()
  keys <- c("module_name", "fleet", "label", "year_i", "age", "length")
  for (case in cases) {
    name <- case[["name"]]
    check_recruitment_process <- function(report, estimates, native_process, tolerance) {
      mode <- case[["recruitment_process"]][["mode"]]
      family <- case[["recruitment_process"]][["family"]]
      values <- unname(unlist(estimates[[mode]]))
      sigma <- exp(unname(unlist(estimates[["log_sd"]])))
      rzero <- exp(unname(unlist(estimates[["log_rzero"]])))
      steep <- 0.2 + 0.8 * stats::plogis(unname(unlist(estimates[["logit_steep"]])))
      phi_0 <- unname(unlist(report[["unfished_spawning_biomass"]]))[[1]] / rzero
      spawners <- unname(unlist(report[["spawning_biomass"]]))[1:4]
      mean_recruitment <- 0.8 * rzero * steep * spawners /
        (0.2 * phi_0 * rzero * (1 - steep) + spawners * (steep - 0.2))
      expected <- if (mode == "log_devs") rep(0, 4L) else log(mean_recruitment)
      density_values <- if (family == "dlnorm") log(values) else values
      nll <- -sum(stats::dnorm(density_values, expected, sigma, log = TRUE))
      expect_equal(values, native_process[["values"]], tolerance = tolerance, info = name)
      expect_equal(expected, native_process[["expected"]], tolerance = tolerance, info = name)
      expect_equal(nll, native_process[["nll"]], tolerance = tolerance, info = name)
      expect_equal(sigma, native_process[["sd"]], info = name)
      actual <- tibble::tibble(label = report[["nll_component_labels"]],
        fleet = report[["nll_component_fleets"]], nll = report[["nll_components"]])
      expect_equal(actual[["nll"]][actual[["label"]] == "recruitment_process"],
        native_process[["nll"]], tolerance = tolerance, info = name)
      components <- actual |>
        dplyr::inner_join(native_process[["observation_components"]], by = c("fleet", "label"),
          suffix = c("_julia", "_native"), relationship = "one-to-one")
      expect_equal(nrow(components), nrow(native_process[["observation_components"]]))
      expect_equal(components[["nll_julia"]], components[["nll_native"]],
        tolerance = tolerance, info = name)
      expect_equal(sum(actual[["nll"]]), native_process[["nll"]] +
        sum(native_process[["observation_components"]][["nll"]]),
        tolerance = tolerance, info = name)
      realized <- if (mode == "log_r") exp(values) else mean_recruitment * exp(values)
      expect_equal(unname(unlist(report[["expected_recruitment"]]))[2:5], realized,
        tolerance = 1e-12, info = name)
      if (family == "dlnorm") {
        expect_true(all(values > 0))
        expect_equal(-sum(stats::dlnorm(values, expected, sigma, log = TRUE)) - nll,
          sum(log(values)), tolerance = 1e-10, info = name)
      }
    }
    check_observation_reports <- function(report, native_report, native_likelihood, tolerance) {
      for (field in c("catch_numbers", "index_numbers", "catch_weight", "index_weight",
        "catch_numbers_at_age", "index_numbers_at_age", "catch_weight_at_age", "index_weight_at_age",
        "catch_numbers_at_length", "index_numbers_at_length", "agecomp_proportion",
        "lengthcomp_proportion", "age_to_length_conversion_derived")) {
        expect_equal(unname(unlist(report[[field]])), unname(unlist(native_report[[field]])),
          tolerance = tolerance, info = paste(name, field))
      }
      native_components <- native_likelihood |>
        dplyr::summarize(nll = -sum(.data$lpdf), .by = c("fleet", "label"))
      actual_components <- tibble::tibble(
        fleet = report[["nll_component_fleets"]],
        label = report[["nll_component_labels"]],
        nll = report[["nll_components"]]
      ) |>
        dplyr::inner_join(native_components, by = c("fleet", "label"),
          suffix = c("_julia", "_native"), relationship = "one-to-one")
      expect_equal(nrow(actual_components), nrow(native_components))
      expect_equal(actual_components[["nll_julia"]], actual_components[["nll_native"]],
        tolerance = tolerance, info = name)
      expect_equal(sum(report[["nll_components"]]), as.numeric(native_report[["jnll"]]),
        tolerance = tolerance, info = name)
      expected_rows <- native_likelihood
      for (index in seq_len(nrow(expected_rows))) {
        row <- expected_rows[index, ]
        fleet_index <- match(row[["fleet"]], config[["fleet_names"]])
        year <- row[["year_i"]]
        label <- row[["label"]]
        if (grepl("comp", label)) {
          lpdf <- fit_result[["report"]][[paste0(sub("_expected$", "", label),
            "_log_likelihood_by_fleet")]][year, fleet_index]
        } else {
          type <- sub("_expected$", "", label)
          observed <- julia_input[["data"]][[paste0("observed_", type)]][year, fleet_index]
          expected <- report[[label]][[fleet_index]][[year]]
          family <- config[[paste0(type, "_distribution")]]
          family <- if (is.matrix(family)) family[year, fleet_index] else family
          sigma <- config[[paste0(type, "_sigma")]][year, fleet_index]
          lpdf <- if (observed == -999) 0 else if (family == "dnorm") {
            stats::dnorm(observed, expected, sigma, log = TRUE)
          } else {
            stats::dlnorm(observed, log(expected), sigma, log = TRUE)
          }
        }
        expect_equal(as.numeric(lpdf), row[["lpdf"]], tolerance = tolerance,
          info = paste(name, row[["fleet"]], label, year))
        if (row[["missing"]]) expect_equal(as.numeric(lpdf), 0)
      }
    }
    case_parameters <- case[["parameters"]]
    if (!is.null(case[["proportion_female_length"]])) {
      case_parameters <- dplyr::bind_rows(
        case_parameters |> dplyr::filter(.data$label != "proportion_female"),
        case_parameters |>
          dplyr::filter(.data$label == "proportion_female") |>
          dplyr::arrange(dplyr::desc(.data$age))
      )
    }
    if (!is.null(case[["selectivity_lengths"]])) {
      case_parameters <- dplyr::bind_rows(
        case_parameters |> dplyr::filter(.data$module_name != "Selectivity"),
        case_parameters |>
          dplyr::filter(.data$module_name == "Selectivity") |>
          dplyr::arrange(dplyr::desc(.data$fleet), dplyr::desc(.data$timing), dplyr::desc(.data$age))
      )
    }
    input <- initialize_fims(
      case_parameters, FIMSFrame(case[["data"]]), priors = case[["priors"]]
    )
    config <- attr(input, "julia_model_config")
    if (!is.null(case[["selectivity_lengths"]])) {
      selectivity <- case[["parameters"]] |>
        dplyr::filter(.data$module_name == "Selectivity") |>
        dplyr::arrange(match(.data$fleet, config[["fleet_names"]]), .data$timing, .data$age)
      serialized <- attr(input, "julia_input")[["parameters"]][["logit_sel_at_age"]]
      expect_equal(serialized, unname(selectivity[["value"]]), info = name)
      expect_equal(config[["selectivity_parameter_lengths"]], case[["selectivity_lengths"]])
      expect_equal(config[["selectivity_parameter_offsets"]],
        c(1L, 1L + case[["selectivity_lengths"]][[1]]))
      expect_equal(unname(tail(config[["fixed_parameter_mask"]], nrow(selectivity))),
        selectivity[["estimation_type"]] == "fixed_effects")
    }
    config[["diagnostic_file"]] <- file.path(
      tempdir(), paste0("fims-configuration-", name, ".progress")
    )
    attr(input, "julia_model_config") <- config
    fit <- fit_fims(input, control = list(iter.max = 400, eval.max = 1000))
    expect_equal(get_opt(fit)[["convergence"]], 0L, info = name)
    expect_true(get_sdreport(fit)[["pdHess"]], info = name)
    expect_true(get_max_gradient(fit) < 1e-3, info = name)
    expect_equal(get_opt(fit)[["objective"]], case[["marginal"]],
      tolerance = 1e-6, info = name)
    expect_equal(get_report(fit)[["jnll"]], case[["report"]][["jnll"]],
      tolerance = 1e-6, info = name)
    parameters <- get_estimates(fit) |>
      dplyr::filter(.data$estimation_type %in% c("fixed_effects", "random_effects"))
    reference <- case[["parameters_table"]]
    if (!is.null(case[["selectivity_lengths"]])) {
      scalar_fleets <- config[["fleet_names"]][case[["selectivity_lengths"]] == 1L]
      # Historical native output labels a scalar slot with the first age.
      reference <- reference |>
        dplyr::mutate(age = dplyr::if_else(
          .data$module_name == "Selectivity" & .data$fleet %in% scalar_fleets,
          NA_real_, .data$age
        ))
      constants <- get_estimates(fit) |>
        dplyr::filter(.data$module_name == "Selectivity", .data$estimation_type == "constant")
      expected_constants <- selectivity |>
        dplyr::filter(.data$estimation_type == "constant") |>
        dplyr::rename(year_i = "timing")
      matched_constants <- dplyr::inner_join(constants, expected_constants,
        by = c("module_name", "fleet", "label", "year_i", "age"),
        relationship = "one-to-one")
      expect_equal(nrow(matched_constants), nrow(expected_constants))
      expect_equal(unname(matched_constants[["estimated"]]), unname(matched_constants[["value"]]))
      expect_true(all(is.na(constants[["uncertainty"]])))
    }
    matched <- dplyr::inner_join(
      reference, parameters, by = keys,
      suffix = c("_native", "_julia"), relationship = "one-to-one"
    )
    expect_equal(nrow(parameters), nrow(reference), info = name)
    expect_equal(nrow(matched), nrow(reference), info = name)
    expect_equal(matched[["estimated_julia"]], matched[["estimated_native"]],
      tolerance = 1e-4, info = name)
    expect_equal(unname(matched[["uncertainty_julia"]]),
      unname(matched[["uncertainty_native"]]), tolerance = 1e-4, info = name)
    objective <- get_obj(fit)
    fit_result <- environment(objective[["fn"]])[["fit_result"]]
    covariance <- fit_result[["covariance"]]
    indices <- matched[["parameter_id"]]
    expect_equal(unname(covariance[indices, indices]), case[["covariance"]],
      tolerance = 1e-4, info = name)
    derived <- get_estimates(fit) |>
      dplyr::filter(.data$estimation_type == "derived_quantity") |>
      dplyr::inner_join(
        case[["derived"]], by = keys,
        suffix = c("_julia", "_native"), relationship = "one-to-one"
      )
    expect_equal(nrow(derived), nrow(case[["derived"]]), info = name)
    for (label in unique(case[["derived"]][["label"]])) {
      rows <- derived |> dplyr::filter(.data$label == .env$label)
      expect_equal(unname(rows[["uncertainty_julia"]]),
        unname(rows[["uncertainty_native"]]), tolerance = 1e-4,
        info = paste(name, label))
      if (identical(name, "DoubleLogistic-joint") || !is.null(case[["selectivity_lengths"]]) ||
          !is.null(case[["growth_variability"]]) || !is.null(case[["proportion_female_length"]]) ||
          !is.null(case[["length_bins"]]) || !is.null(case[["recruitment_process"]])) {
        expect_equal(unname(rows[["estimated"]]), unname(rows[["estimate"]]),
          tolerance = 1e-4, info = paste(name, label))
      }
    }
    fixed_rows <- matched |>
      dplyr::filter(.data$estimation_type_native == "fixed_effects")
    fixed_ids <- which(config[["fixed_parameter_mask"]])
    fixed_order <- match(fixed_rows[["parameter_id"]], fixed_ids)
    expect_setequal(fixed_order, seq_along(objective[["par"]]))
    if (identical(name, "DoubleLogistic-joint") || !is.null(case[["selectivity_lengths"]])) {
      expect_equal(config[["selectivity_types"]],
        rep(if (identical(name, "DoubleLogistic-joint")) "DoubleLogistic" else "AgeSpecific", 2))
      expect_equal(sum(reference[["module_name"]] == "Selectivity"),
        if (identical(name, "DoubleLogistic-joint")) 8L else
          sum(selectivity[["estimation_type"]] == "fixed_effects"))
      expect_equal(sum(reference[["estimation_type"]] == "random_effects"), 4L)
    }
    if (!is.null(case[["joint_hessian"]]) && is.null(case[["conditional"]])) {
      julia_input <- attr(input, "julia_input")
      joint_config <- config
      joint_config[["fixed_parameter_mask"]] <-
        config[["fixed_parameter_mask"]] | config[["random_parameter_mask"]]
      joint_config[["random_parameter_mask"]] <- rep(FALSE, length(config[["random_parameter_mask"]]))
      active_ids <- which(joint_config[["fixed_parameter_mask"]])
      joint_order <- match(indices, active_ids)
      expect_equal(as.matrix(fit_result[["hessian"]])[indices, indices],
        case[["joint_hessian"]], tolerance = 1e-4, info = name)
      expect_equal(objective[["he"]](objective[["par"]])[fixed_order, fixed_order],
        unname(case[["fixed_hessian"]]), tolerance = 1e-4, info = name)
    }
    if (!is.null(case[["recruitment_process"]])) {
      expect_equal(config[["recruitment"]], "beverton_holt")
      expect_equal(config[["recruitment_process_mode"]], case[["recruitment_process"]][["mode"]])
      expect_equal(config[["recruitment_process_distribution"]],
        case[["recruitment_process"]][["family"]])
      expect_equal(sum(config[["random_parameter_mask"]]), 4L)
      check_recruitment_process(fit_result[["report"]], fit_result[["estimates"]],
        case[["process"]], tolerance = 1e-4)
    }
    if (!is.null(case[["length_bins"]])) {
      expect_equal(julia_input[["data"]][["n_lengths_by_fleet"]],
        unname(lengths(case[["length_bins"]])))
      for (fleet_index in seq_along(config[["fleet_names"]])) {
        fleet_name <- config[["fleet_names"]][[fleet_index]]
        expected_bins <- case[["length_bins"]][[fleet_name]]
        for (label in c("lengthcomp_expected", "lengthcomp_proportion",
          "catch_numbers_at_length", "index_numbers_at_length")) {
          rows <- get_estimates(fit) |>
            dplyr::filter(.data$fleet == .env$fleet_name, .data$label == .env$label,
              .data$type == "derived_quantity") |>
            dplyr::arrange(.data$year_i, .data$length)
          expect_equal(nrow(rows), 5L * length(expected_bins), info = paste(name, label))
          expect_equal(rows[["length"]], rep(expected_bins, 5L), info = paste(name, label))
        }
      }
      for (type in c("catch", "index")) {
        data_rows <- case[["model_data"]] |>
          dplyr::filter(.data$type == .env$type, .data$observed != -999)
        for (index in seq_len(nrow(data_rows))) {
          row <- data_rows[index, ]
          parsed <- FIMS:::parse_data_distribution(row[["uncertainty"]])
          family <- parsed[["family"]][[1]]
          configured <- config[[paste0(type, "_distribution")]]
          fleet_index <- match(row[["fleet"]], config[["fleet_names"]])
          configured <- if (is.matrix(configured)) configured[row[["timing"]], fleet_index] else configured
          expect_equal(configured, family)
          scale <- unlist(parsed[[if (family == "dnorm") "sd" else "sdlog"]])
          expect_equal(config[[paste0(type, "_sigma")]][row[["timing"]], fleet_index],
            as.numeric(scale))
        }
      }
      check_observation_reports(get_report(fit), case[["report"]],
        case[["observation_likelihood"]], tolerance = 1e-4)
    }
    if (!is.null(case[["growth_variability"]])) {
      expect_equal(config[["growth_model_type"]], "VonBertalanffySchnute")
      expect_false("growth_log_length_sd_at_young" %in% names(julia_input[["parameters"]]))
      variability_labels <- c(
        "log_sd_mean_length_young", "log_sd_mean_length_old", "log_sd_growth_coefficient",
        "mean_length_young_mean_length_old_logit_corr",
        "mean_length_young_growth_coefficient_logit_corr",
        "mean_length_old_growth_coefficient_logit_corr"
      )
      starts <- case_parameters |>
        dplyr::filter(.data$module_name == "Growth", .data$label %in% variability_labels) |>
        dplyr::arrange(match(.data$label, variability_labels))
      expect_equal(unname(unlist(julia_input[["parameters"]][paste0("growth_", variability_labels)])),
        unname(starts[["value"]]))
      natural <- dplyr::inner_join(case[["natural_growth"]], parameters, by = keys,
        suffix = c("_native", "_julia"), relationship = "one-to-one")
      expect_equal(nrow(natural), nrow(case[["natural_growth"]]))
      log_sd <- grepl("^log_sd_", natural[["label"]])
      values <- natural[["estimated_julia"]]
      standard_errors <- natural[["uncertainty_julia"]]
      standard_errors[log_sd] <- exp(values[log_sd]) * standard_errors[log_sd]
      values[log_sd] <- exp(values[log_sd])
      expect_equal(unname(values), natural[["estimated_native"]], tolerance = 1e-4)
      expect_equal(unname(standard_errors), natural[["uncertainty_native"]], tolerance = 1e-4)
      natural_ids <- natural[["parameter_id"]]
      expect_equal(unname(diag(values) %*% covariance[natural_ids, natural_ids] %*% diag(values)),
        case[["natural_growth_covariance"]], tolerance = 1e-4)
      probe_rows <- dplyr::inner_join(case[["variability_probe_rows"]], get_estimates(fit),
        by = keys, relationship = "one-to-one")
      expect_equal(nrow(probe_rows), nrow(case[["variability_probe_rows"]]))
      probe_ids <- probe_rows[["parameter_id"]]
      probe_config <- joint_config
      probe_config[["fixed_parameter_mask"]][probe_ids] <- TRUE
      probe_active_ids <- which(probe_config[["fixed_parameter_mask"]])
      probe_order <- match(probe_ids, probe_active_ids)
      for (field in c("growth_mean_LAA", "growth_sd_LAA", "growth_mean_WAA",
        "growth_derived_mean_WAA", "age_to_length_conversion_derived",
        "age_to_length_conversion_derived_used", "nll_components")) {
        expect_equal(unname(unlist(get_report(fit)[[field]])),
          unname(unlist(case[["report"]][[field]])), tolerance = 1e-4, info = paste(name, field))
      }
    }
    if (!is.null(case[["proportion_female_length"]])) {
      female_rows <- get_estimates(fit) |>
        dplyr::filter(.data$module_name == "Population", .data$label == "proportion_female") |>
        dplyr::arrange(.data$age)
      expected_female <- case[["parameters"]] |>
        dplyr::filter(.data$label == "proportion_female") |>
        dplyr::arrange(.data$age)
      expect_equal(nrow(female_rows), nrow(expected_female))
      expect_equal(female_rows[["age"]], expected_female[["age"]])
      expect_equal(unname(female_rows[["estimated"]]), unname(expected_female[["value"]]))
      expect_equal(unname(julia_input[["parameters"]][["proportion_female"]]),
        unname(expected_female[["value"]]))
      expect_false(any(config[["fixed_parameter_mask"]][female_rows[["parameter_id"]]]))
      expect_false(any(config[["random_parameter_mask"]][female_rows[["parameter_id"]]]))
      expect_true(all(is.na(female_rows[["uncertainty"]])))
      probe_rows <- dplyr::inner_join(case[["female_probe_rows"]], get_estimates(fit),
        by = keys, relationship = "one-to-one")
      expect_equal(nrow(probe_rows), nrow(case[["female_probe_rows"]]))
      probe_ids <- probe_rows[["parameter_id"]]
      probe_config <- joint_config
      probe_config[["fixed_parameter_mask"]][probe_ids] <- TRUE
      probe_active_ids <- which(probe_config[["fixed_parameter_mask"]])
      probe_order <- match(probe_ids, probe_active_ids)
      for (field in c("unfished_spawning_biomass", "spawning_biomass_ratio", "nll_components")) {
        expect_equal(unname(unlist(get_report(fit)[[field]])),
          unname(unlist(case[["report"]][[field]])), tolerance = 1e-4, info = paste(name, field))
      }
    }
    if (!is.null(case[["conditional"]])) {
      config <- environment(objective[["fn"]])[["model_config"]]
      julia_input <- attr(input, "julia_input")
      prior_indices <- c(1L, 1L, 2L, 2L, 2L, 1L)
      deviation_priors <- case[["priors"]] |>
        dplyr::filter(.data$label == "log_devs")
      deviation_years <- case[["parameters"]] |>
        dplyr::filter(.data$module_name == "Recruitment", .data$label == "log_devs") |>
        dplyr::arrange(.data$timing) |>
        dplyr::pull(.data$timing)
      prior_indices <- c(prior_indices, match(deviation_priors[["timing"]], deviation_years))
      expect_equal(config[["parameter_prior_components"]], case[["priors"]][["label"]])
      expect_equal(config[["parameter_prior_indices"]], prior_indices)
      expect_equal(config[["parameter_prior_transforms"]],
        rep("identity", nrow(case[["priors"]])))
      expect_equal(config[["parameter_prior_distributions"]], case[["priors"]][["distribution"]])
      expect_equal(unname(config[["parameter_prior_means"]]), unname(case[["priors"]][["mean"]]))
      expect_equal(config[["parameter_prior_sds"]], case[["priors"]][["sd"]])
      expect_equal(as.matrix(fit_result[["hessian"]])[indices, indices],
        case[["joint_hessian"]], tolerance = 1e-4, info = name)
      expect_equal(objective[["he"]](objective[["par"]])[fixed_order, fixed_order],
        case[["fixed_hessian"]], tolerance = 1e-4, info = name)
      prior_count <- nrow(case[["priors"]])
      expect_equal(as.numeric(fit_result[["report"]][["nll_components"]])[seq_len(prior_count)],
        case[["prior_nll_components"]], tolerance = 1e-4, info = name)
      joint_config <- config
      joint_config[["fixed_parameter_mask"]] <-
        config[["fixed_parameter_mask"]] | config[["random_parameter_mask"]]
      joint_config[["random_parameter_mask"]] <- rep(FALSE, length(config[["random_parameter_mask"]]))
      active_ids <- which(joint_config[["fixed_parameter_mask"]])
      joint_order <- match(indices, active_ids)
      random_order <- which(reference[["estimation_type"]] == "random_effects")
      fixed_only_config <- joint_config
      fixed_priors <- config[["parameter_prior_components"]] != "log_devs"
      for (field in c(
        "parameter_prior_components", "parameter_prior_indices", "parameter_prior_transforms",
        "parameter_prior_distributions", "parameter_prior_means", "parameter_prior_sds"
      )) {
        fixed_only_config[[field]] <- config[[field]][fixed_priors]
      }
      point_modes <- point_curvature <- list()
    }
    for (point in case[["points"]]) {
      values <- objective[["par"]]
      values[fixed_order] <- point[["fixed"]]
      expect_equal(objective[["fn"]](values), as.numeric(point[["marginal"]]),
        tolerance = 1e-8, info = name)
      expect_equal(unname(objective[["gr"]](values)[fixed_order]),
        point[["gradient"]], tolerance = 1e-6, info = name)
      if (!is.null(case[["joint_hessian"]]) && is.null(case[["conditional"]])) {
        evaluated <- FIMS:::evaluate_julia_fixed_objective(julia_input, config, values, 3L)
        parameter_vector <- purrr::flatten_dbl(evaluated[["estimates"]][names(julia_input[["parameters"]])])
        expect_equal(parameter_vector[indices], point[["parameters"]],
          tolerance = 1e-8, info = name)
        joint_values <- parameter_vector[active_ids]
        joint_hessian <- FIMS:::evaluate_julia_fixed_objective(
          julia_input, joint_config, joint_values, 2L
        )
        expect_equal(as.matrix(joint_hessian)[joint_order, joint_order],
          point[["joint_hessian"]], tolerance = 1e-6, info = name)
        score <- FIMS:::evaluate_julia_fixed_objective(julia_input, joint_config, joint_values, 1L)
        expect_equal(as.numeric(score)[joint_order], point[["joint_gradient"]],
          tolerance = 1e-6, info = name)
        probe_reference <- point[["variability_probe"]]
        if (!is.null(point[["female_probe"]])) probe_reference <- point[["female_probe"]]
        if (!is.null(probe_reference)) {
          expect_equal(parameter_vector[probe_ids], probe_reference[["parameters"]],
            tolerance = 1e-8, info = name)
          probe_values <- parameter_vector[probe_active_ids]
          probe_gradient <- FIMS:::evaluate_julia_fixed_objective(
            julia_input, probe_config, probe_values, 1L
          )
          probe_hessian <- FIMS:::evaluate_julia_fixed_objective(
            julia_input, probe_config, probe_values, 2L
          )
          expect_equal(as.numeric(probe_gradient)[probe_order],
            probe_reference[["gradient"]], tolerance = 1e-6, info = name)
          expect_equal(as.matrix(probe_hessian)[probe_order, probe_order],
            probe_reference[["hessian"]], tolerance = 1e-6, info = name)
          if (!is.null(point[["female_probe"]]) &&
              identical(point[["fixed"]], case[["points"]][[1]][["fixed"]])) {
            counterfactual_values <- probe_values
            female_active_ids <- match(female_rows[["parameter_id"]], probe_active_ids)
            counterfactual_values[female_active_ids] <- case[["female_counterfactual"]][["values"]]
            counterfactual <- FIMS:::evaluate_julia_fixed_objective(
              julia_input, probe_config, counterfactual_values, 3L
            )
            native_counterfactual <- case[["female_counterfactual"]][["report"]]
            expect_equal(counterfactual[["nll"]], as.numeric(native_counterfactual[["jnll"]]),
              tolerance = 1e-8, info = name)
            for (field in c("spawning_biomass", "expected_recruitment", "nll_components")) {
              expect_equal(unname(unlist(counterfactual[["report"]][[field]])),
                unname(unlist(native_counterfactual[[field]])), tolerance = 1e-8,
                info = paste(name, "counterfactual", field))
            }
          }
        }
        if (identical(name, "AgeSpecific-year-by-age") &&
            identical(point[["fixed"]], case[["points"]][[1]][["fixed"]])) {
          permutations <- list(
            year_age_transpose = c(as.numeric(t(matrix(seq_len(60L), nrow = 12L))), 61:72),
            swapped_years = c(13:24, 1:12, 25:72),
            swapped_fleet_blocks = c(61:72, 13:60, 1:12)
          )
          for (permutation in permutations) {
            corrupted_input <- julia_input
            corrupted_input[["parameters"]] <-
              evaluated[["estimates"]][names(julia_input[["parameters"]])]
            corrupted_input[["parameters"]][["logit_sel_at_age"]] <-
              corrupted_input[["parameters"]][["logit_sel_at_age"]][permutation]
            corrupted_values <- purrr::flatten_dbl(corrupted_input[["parameters"]])
            corrupted <- FIMS:::evaluate_julia_fixed_objective(
              corrupted_input, joint_config, corrupted_values[active_ids], 3L
            )
            expect_gt(abs(corrupted[["nll"]] - point[["report"]][["jnll"]]), 1e-2)
            expect_gt(max(abs(unlist(corrupted[["report"]][["mortality_F"]]) -
              unlist(point[["report"]][["mortality_F"]]))), 1e-4)
          }
        }
      }
      if (!is.null(case[["conditional"]])) {
        evaluated <- FIMS:::evaluate_julia_fixed_objective(julia_input, config, values, 3L)
        parameter_vector <- purrr::flatten_dbl(evaluated[["estimates"]][names(julia_input[["parameters"]])])
        expect_equal(parameter_vector[indices], point[["parameters"]],
          tolerance = 1e-8, info = name)
        expect_equal(evaluated[["nll"]], point[["joint"]], tolerance = 1e-8, info = name)
        expect_equal(as.numeric(evaluated[["report"]][["nll_components"]])[seq_len(prior_count)],
          point[["prior_nll_components"]], tolerance = 1e-8, info = name)
        joint_values <- parameter_vector[active_ids]
        joint_hessian <- FIMS:::evaluate_julia_fixed_objective(
          julia_input, joint_config, joint_values, 2L
        )
        joint_hessian <- as.matrix(joint_hessian)[joint_order, joint_order]
        expect_equal(joint_hessian, point[["joint_hessian"]], tolerance = 1e-6, info = name)
        random_hessian <- joint_hessian[random_order, random_order]
        expect_equal(objective[["fn"]](values) - evaluated[["nll"]],
          as.numeric(determinant(random_hessian, logarithm = TRUE)[["modulus"]]) / 2 -
            length(random_order) * log(2 * pi) / 2, tolerance = 1e-8, info = name)
        score <- FIMS:::evaluate_julia_fixed_objective(julia_input, joint_config, joint_values, 1L)
        prior_coordinates <- case[["prior_coordinates"]]
        prior_score <- purrr::pmap_dbl(list(
          value = point[["parameters"]][prior_coordinates],
          distribution = case[["priors"]][["distribution"]],
          mean = case[["priors"]][["mean"]],
          sd = case[["priors"]][["sd"]]
        ), function(value, distribution, mean, sd) {
          switch(distribution,
            dnorm = (value - mean) / sd^2,
            dlnorm = (1 + (log(value) - mean) / sd^2) / value,
            stop("Unsupported independent prior-score family.")
          )
        })
        expected_score <- point[["native_gradient"]]
        expected_score[prior_coordinates] <- expected_score[prior_coordinates] + prior_score
        expect_equal(as.numeric(score)[joint_order], expected_score, tolerance = 1e-6, info = name)
        expect_lt(max(abs(as.numeric(score)[joint_order][random_order])), 1e-6,
          label = paste(name, "conditional random score"))
        baseline_hessian <- FIMS:::evaluate_julia_fixed_objective(
          julia_input, fixed_only_config, joint_values, 2L
        )
        baseline_hessian <- as.matrix(baseline_hessian)[joint_order, joint_order]
        expect_equal(random_hessian - baseline_hessian[random_order, random_order],
          point[["prior_random_hessian"]], tolerance = 1e-8, info = name)
        expect_equal(baseline_hessian[random_order, random_order],
          point[["native_random_hessian"]], tolerance = 1e-6, info = name)
        point_modes[[length(point_modes) + 1L]] <- parameter_vector[indices][random_order]
        point_curvature[[length(point_curvature) + 1L]] <- random_hessian
      }
      report <- objective[["report"]](values)
      if (!is.null(case[["recruitment_process"]])) {
        check_recruitment_process(evaluated[["report"]], evaluated[["estimates"]],
          point[["process"]], tolerance = 1e-8)
      }
      if (!is.null(case[["length_bins"]])) {
        fit_result <- FIMS:::evaluate_julia_fixed_objective(julia_input, config, values, 3L)
        check_observation_reports(report, point[["report"]],
          point[["observation_likelihood"]], tolerance = 1e-8)
      }
      if (!is.null(case[["proportion_female_length"]])) {
        for (field in c("unfished_spawning_biomass", "spawning_biomass_ratio", "nll_components")) {
          expect_equal(unname(unlist(report[[field]])),
            unname(unlist(point[["report"]][[field]])), tolerance = 1e-8, info = paste(name, field))
        }
      }
      if (!is.null(case[["growth_variability"]])) {
        for (field in c("growth_mean_LAA", "growth_sd_LAA", "growth_mean_WAA",
          "growth_derived_mean_WAA", "age_to_length_conversion_derived",
          "age_to_length_conversion_derived_used", "nll_components")) {
          expect_equal(unname(unlist(report[[field]])),
            unname(unlist(point[["report"]][[field]])), tolerance = 1e-8, info = paste(name, field))
        }
      }
      for (field in c(
        "jnll", "numbers_at_age", "biomass", "spawning_biomass",
        "expected_recruitment", "mortality_F", "mortality_M", "mortality_Z",
        "catch_expected", "index_expected", "agecomp_expected", "lengthcomp_expected"
      )) {
        expect_equal(unname(unlist(report[[field]])),
          unname(unlist(point[["report"]][[field]])), tolerance = 1e-8,
          info = paste(name, field))
      }
    }
    if (!is.null(case[["conditional"]])) {
      random_prior_results[[name]] <- list(
        modes = point_modes, curvature = point_curvature,
        covariance = covariance[indices, indices]
      )
    }
  }
  control <- random_prior_results[["EWAA-fixed-prior-control"]]
  augmented <- random_prior_results[["EWAA-random-priors"]]
  native_control <- random_prior_oracle[["cases"]][["EWAA-fixed-prior-control"]]
  native_augmented <- random_prior_oracle[["cases"]][["EWAA-random-priors"]]
  random_order <- which(native_augmented[["parameters_table"]][["estimation_type"]] == "random_effects")
  for (index in seq_along(native_control[["points"]])) {
    expect_equal(augmented[["modes"]][[index]] - control[["modes"]][[index]],
      (native_augmented[["points"]][[index]][["parameters"]] -
        native_control[["points"]][[index]][["parameters"]])[random_order], tolerance = 1e-8)
    expect_equal(augmented[["curvature"]][[index]] - control[["curvature"]][[index]],
      native_augmented[["points"]][[index]][["random_hessian"]] -
        native_control[["points"]][[index]][["random_hessian"]], tolerance = 1e-6)
  }
  expect_equal(augmented[["covariance"]] - control[["covariance"]],
    native_augmented[["covariance"]] - native_control[["covariance"]], tolerance = 1e-4)
})

test_that("Julia likelihood plots count equal-valued components separately", {
  estimates <- tibble::tibble(
    value_log_rzero = rep(c(1, 2), each = 3),
    label = rep(c("catch_expected", "catch_expected", "parameter_prior"), 2),
    type = "likelihood", lpdf = c(-1, -1, -2, -3, -3, -4)
  )
  expect_no_warning(plot <- plot_likelihood(list(vec = c(1, 2), estimates = estimates)))
  totals <- plot[["data"]] |>
    dplyr::filter(.data$group_clean == "Total")
  expect_equal(totals[["total_like"]], c(-4, -10))
  expect_equal(totals[["total_like_change"]], c(0, 6))
})

test_that("real Julia profiles and retrospective refits retain their priors", {
  skip_if(Sys.getenv("FIMS_RUN_JULIA_INTEGRATION") != "true",
    "Set FIMS_RUN_JULIA_INTEGRATION=true to exercise real Julia diagnostics.")
  raw <- data_big |>
    dplyr::filter(
      !.data$type %in% c("length_comp", "age_to_length_conversion"),
      dplyr::if_else(.data$type == "weight_at_age", .data$timing <= 6, .data$timing <= 5)
    )
  data <- FIMSFrame(raw)
  parameters <- setup_default_parameters(data) |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(.data$label == "log_rzero", "fixed_effects", "constant"),
      distribution_type = NA_character_, distribution = NA_character_
    )
  priors <- tibble::tibble(
    module_name = "Recruitment", fleet = NA_character_, label = "log_rzero",
    timing = NA_real_, age = NA_real_, distribution = "dnorm",
    mean = log(1e6), sd = 0.5
  )
  fit <- initialize_fims(parameters, data, priors = priors) |>
    fit_fims(number_of_loops = 0)
  expect_equal(get_opt(fit)[["convergence"]], 0L)
  expect_true(get_sdreport(fit)[["pdHess"]])
  components <- get_estimates(fit) |>
    dplyr::filter(.data$type == "likelihood")
  expect_true(nrow(components) > 0L)
  expect_equal(-sum(components[["lpdf"]]), get_report(fit)[["jnll"]])
  expect_true("parameter_prior" %in% components[["label"]])
  profile <- run_fims_likelihood(
    fit, parameters, raw, parameter_name = "log_rzero",
    n_cores = 1, min = -0.01, max = 0.01, length = 3
  )
  optimum <- get_estimates(fit) |>
    dplyr::filter(.data$label == "log_rzero") |>
    dplyr::pull(.data$estimated)
  expect_equal(profile[["vec"]], optimum + c(-0.01, 0, 0.01))
  profiled_estimates <- profile[["estimates"]] |>
    dplyr::filter(.data$label == "log_rzero")
  expect_equal(profiled_estimates[["estimated"]], profile[["vec"]])
  expect_true(all(profiled_estimates[["estimation_type"]] == "constant"))
  expect_no_warning(plot <- plot_likelihood(profile))
  expect_s3_class(plot, "ggplot")
  expect_true(nrow(plot[["data"]]) > 0L)
  retrospective <- run_fims_retrospective(
    0:1, raw, parameters, n_cores = 1, priors = priors
  )
  expect_setequal(unique(retrospective[["estimates"]][["retrospective_peel"]]), 0:1)
  retrospective_parameters <- retrospective[["estimates"]] |>
    dplyr::filter(.data$label == "log_rzero")
  expect_equal(nrow(retrospective_parameters), 2L)
  expect_true(all(is.finite(retrospective_parameters[["estimated"]])))
  expect_identical(attr(get_input(fit), "julia_priors"), priors)
  expect_true(is.finite(generics::glance(fit)[["marginal_nll"]]))
  parallel_profile <- run_fims_likelihood(
    fit, parameters, raw, parameter_name = "log_rzero",
    n_cores = 2, min = -0.01, max = 0.01, length = 3
  )
  expect_equal(parallel_profile, profile, tolerance = 1e-8)
  expect_equal(future::nbrOfWorkers(), 1L)
  parallel_retrospective <- run_fims_retrospective(
    0:1, raw, parameters, n_cores = 2, priors = priors
  )
  expect_equal(parallel_retrospective, retrospective, tolerance = 1e-8)
  expect_equal(future::nbrOfWorkers(), 1L)
})
